param(
    [Parameter(Mandatory=$true, HelpMessage='Ruta de búsqueda')]
    [string]$Ruta
)

# Validar que la ruta existe
if (-Not (Test-Path -Path $Ruta)) {
    Write-Host "Error: La ruta '$Ruta' no existe." -ForegroundColor Red
    exit 1
}

Write-Host "Buscando carpetas vacías en: $Ruta" -ForegroundColor Cyan

# Obtener todos los directorios recursivamente
$directorios = Get-ChildItem -Path $Ruta -Directory -Recurse

# Filtrar los que están vacíos
$carpetasVacias = $directorios | Where-Object {
    (Get-ChildItem -Path $_.FullName -Force).Count -eq 0
}

# Mostrar resultados
if ($carpetasVacias.Count -gt 0) {
    Write-Host "`nCarpetas vacías encontradas:" -ForegroundColor Green
    $carpetasVacias | ForEach-Object { Write-Output $_.FullName }
} else {
    Write-Host "No se encontraron carpetas vacías." -ForegroundColor Yellow
}

Write-Host "`nTotal: $($carpetasVacias.Count) carpeta(s) vacía(s)"

param(
    [Parameter(Mandatory=$true)]
    [string]$NombreArchivo,
    [string]$TextoBuscar = '',
    [string]$NuevosAtributos = ''
)

# Buscar el archivo de forma recursiva
$archivo = Get-ChildItem -Path '.' -Recurse -Filter $NombreArchivo `
           -ErrorAction SilentlyContinue | Select-Object -First 1

if (-not $archivo) {
    Write-Host "Archivo '$NombreArchivo' no encontrado." -ForegroundColor Red
    exit 1
}

Write-Host "Archivo encontrado: $($archivo.FullName)" -ForegroundColor Green

# Buscar texto si se especificó
if ($TextoBuscar -ne '') {
    $resultado = Get-Content $archivo.FullName | Select-String -Pattern $TextoBuscar
    if ($resultado) {
        Write-Host "Texto '$TextoBuscar' encontrado." -ForegroundColor Green
    } else {
        Write-Host "Texto '$TextoBuscar' NO encontrado." -ForegroundColor Yellow
    }
}

# Cambiar atributos si se especificaron
if ($NuevosAtributos -ne '') {
    Set-ItemProperty -Path $archivo.FullName -Name Attributes -Value $NuevosAtributos
    Write-Host "Atributos cambiados a: $NuevosAtributos"
}
